var globalFields struct {
 sync.RWMutex
 fields []LogField
}

func AddGlobalFields(fields ...LogField) {
 globalFields.Lock()
 globalFields.fields = append(globalFields.fields, fields...)
 globalFields.Unlock()
}

func globalFieldsSnapshot() []LogField {
 globalFields.RLock()
 defer globalFields.RUnlock()
 return append([]LogField(nil), globalFields.fields...)
}

func addCaller(fields ...LogField) []LogField {
 fields = append(globalFieldsSnapshot(), fields...)
 return append(fields, Field(callerKey, getCaller(callerDepth)))
}

func (l *richLogger) buildFields(fields ...LogField) []LogField {
 fields = append(globalFieldsSnapshot(), l.fields...)
 fields = append(fields, fields...)
 fields = append(fields, Field(callerKey, getCaller(callerDepth+l.callerSkip)))

 if l.ctx == nil {
  return fields
 }

 traceID := traceIdFromContext(l.ctx)
 if len(traceID) > 0 {
  fields = append(fields, Field(traceKey, traceID))
 }

 spanID := spanIdFromContext(l.ctx)
 if len(spanID) > 0 {
  fields = append(fields, Field(spanKey, spanID))
 }

 val := l.ctx.Value(fieldsContextKey)
 if val != nil {
  if arr, ok := val.([]LogField); ok {
   fields = append(fields, arr...)
  }
 }

 return fields
}

func (l *richLogger) buildFields(fields ...LogField) []LogField {
 logFields := append(globalFieldsSnapshot(), l.fields...)
 logFields = append(logFields, fields...)
 logFields = append(logFields, Field(callerKey, getCaller(callerDepth+l.callerSkip)))

 if l.ctx == nil {
  return logFields
 }

