type (
	LogConf  = logx.LogConf
	LogField = logx.LogField
	Writer   = logx.Writer
)

func Field(key string, value interface{}) LogField {
	return logx.Field(key, value)
}

func AddGlobalFields(fields ...LogField) {
	logx.AddGlobalFields(fields...)
}

func Alert(v string) {
	logx.Alert(v)
}

func Close() error {
	return logx.Close()
}

func Disable() {
	logx.Disable()
}

func DisableStat() {
	logx.DisableStat()
}

func Must(err error) {
	logx.Must(err)
}

func MustSetup(c LogConf) {
	logx.MustSetup(c)
}

func Reset() Writer {
	return logx.Reset()
}

func SetLevel(level uint32) {
	logx.SetLevel(level)
}

func SetUp(c LogConf) error {
	return logx.SetUp(c)
}

func SetWriter(w Writer) {
	logx.SetWriter(w)
}

func Error(ctx context.Context, v ...interface{}) {
	logger(ctx).Error(v...)
}

func Errorf(ctx context.Context, format string, v ...interface{}) {
	logger(ctx).Errorf(format, v...)
}

func Errorv(ctx context.Context, v interface{}) {
	logger(ctx).Errorv(v)
}

func Errorw(ctx context.Context, msg string, fields ...LogField) {
	logger(ctx).Errorw(msg, fields...)
}

func Info(ctx context.Context, v ...interface{}) {
	logger(ctx).Info(v...)
}

func Infof(ctx context.Context, format string, v ...interface{}) {
	logger(ctx).Infof(format, v...)
}

func Infov(ctx context.Context, v interface{}) {
	logger(ctx).Infov(v)
}

func Infow(ctx context.Context, msg string, fields ...LogField) {
	logger(ctx).Infow(msg, fields...)
}

func Slow(ctx context.Context, v ...interface{}) {
	logger(ctx).Slow(v...)
}

func Slowf(ctx context.Context, format string, v ...interface{}) {
	logger(ctx).Slowf(format, v...)
}

func Slowv(ctx context.Context, v interface{}) {
	logger(ctx).Slowv(v)
}

func Sloww(ctx context.Context, msg string, fields ...LogField) {
	logger(ctx).Sloww(msg, fields...)
}

func logger(ctx context.Context) logx.Logger {
	return logx.WithContext(ctx).WithCallerSkip(1)
}

